'use strict';
const STUDIO_UI5={bind,render,cityView,menuView,liveView,supplyView,help};
let studioTarget5=state.stores[0]?.id||'new',studioDraft5=null,studioState5=state;
function studioCurrent5(){
 const s=state.stores.find(s=>s.id===studioTarget5),saved=state.studio5.designs.find(d=>d.id===studioTarget5);
 if(studioTarget5!=='new'&&!s&&!saved)studioTarget5=state.stores[0]?.id||'new';
 if(!studioDraft5||studioDraft5.target!==studioTarget5){const store=state.stores.find(s=>s.id===studioTarget5),template=state.studio5.designs.find(d=>d.id===studioTarget5);studioDraft5={target:studioTarget5,name:template?.name||(store?loc(store.id).name+' · můj návrh':'Moje kavárna'),design:store?storeDesign5(store):cloneStudio5(template?.design||studioBaseDesign5())};designSelected='counter';}
 floorDraft={store:studioTarget5,floor:studioDraft5.design.floor};designStore=s?.id||null;return state.stores.find(s=>s.id===studioTarget5)||null;
}
currentDesign5=function(){const s=studioCurrent5();return s||{id:null,seats:100,floor:studioDraft5.design.floor,equipment:Object.fromEntries(Object.entries(studioDraft5.design.equipment).map(([k,model])=>[k,{model,condition:100}]))}};
function studioEquipmentFields5(design){return Object.entries(EQUIPMENT_MODELS5).map(([key,models])=>field(EQUIPMENT[key].name,`<select data-studio-model="${key}">${!['machine','grinder'].includes(key)?option('none','Bez zařízení',design.equipment[key]||'none'):''}${Object.entries(models).map(([model,cfg])=>option(model,cfg.name+' · '+money(cfg.cost),design.equipment[key])).join('')}</select>`)).join('')}
function studioEmpty5(){return `<section class="card"><h2>První kavárna čeká na tvůj výběr.</h2><p>Vyber adresu na mapě nebo nejdřív ulož vlastní půdorys a vybavení.</p><div class="actions"><button class="primary" data-goto="city">Vybrat první adresu</button><button class="soft" data-goto="interior">Navrhnout kavárnu</button></div></section>`}
cityView=function(){if(selected&&loc(selected)?.city===city)return STUDIO_UI5.cityView();const c=CITIES.find(c=>c.name===city);return `<div class="grid"><section class="card"><div class="card-head"><div><h2>${state.stores.length?'Vyber další adresu':'Tvoje první kavárna'}</h2><p>${esc(c.theme)}</p></div><span class="badge">${esc(city)}</span></div>${field('Město',`<select id="citySelect">${CITIES.map(c=>option(c.name,c.name+(unlocked(c.name)?'':' · uzamčeno'),city)).join('')}</select>`)}${map()}<div class="map-legend"><span><i class="dot"></i>Tvoje značka</span><span><i class="dot open"></i>Volná lokalita</span><span><i class="dot rival"></i>Soupeř</span></div><div class="activity">${news(4)}</div></section><div class="stack"><section class="card studio-welcome5"><span class="eyelabel">${state.stores.length?'PROSTOR PRO EXPANZI':'ZAKLÁDÁŠ VLASTNÍ FIRMU'}</span><h2>Adresa je na tobě.</h2><p>Klikni na lokalitu na mapě. Zobrazí se cena, nájem a místní hosté.</p>${rows([['Dostupný kapitál',money(state.cash)],['Vlastní kavárny',state.stores.length],['Uložené návrhy',state.studio5.designs.length]])}<button class="soft wide" data-studio-new>Navrhnout vlastní kavárnu</button><p class="sub">Základní otevření zahrnuje Compact kávovar, Entry mlýnek, filtr, bar a šest čtyřmístných stolů. Vlastní návrh cenu upraví podle vybraného vybavení.</p></section>${milestone()}</div></div>`};
openDialog=function(id,franchise=false){if(franchise){const l=loc(id);show(`<h2>Franšíza · ${esc(l.name)}</h2><p>Partner zajišťuje vybavení. Investice ${money(l.setup*.25)}.</p><div class="fields">${field('Značka',`<select id="openBrand">${brandOptions(state.brands[0].id)}</select>`)}${field('Káva',`<select id="openBlend">${blendOptions(state.blends[0].id)}</select>`)}</div><button class="primary wide" id="openConfirm">Otevřít franšízu</button>`);el('openConfirm').onclick=()=>{try{openStore(id,el('openBrand').value,el('openBlend').value,true);persist();render();el('modal').close();toast('Franšíza otevřena.')}catch(e){toast(e.message)}};return;}
 const l=loc(id);show(`<span class="eyelabel">${esc(l.city.toUpperCase())}</span><h2>Nová kavárna · ${esc(l.name)}</h2><div class="fields">${field('Použít návrh',`<select id="openDesign5">${option('base','Základní kavárna · 24 míst','base')}${state.studio5.designs.map(d=>option(d.id,d.name,'base')).join('')}</select>`)}${field('Značka',`<select id="openBrand">${brandOptions(state.brands[0].id)}</select>`)}${field('Káva',`<select id="openBlend">${blendOptions(state.blends[0].id)}</select>`)}</div><div id="openingPreview5"></div><button class="primary wide" id="openConfirm">Otevřít s tímto návrhem</button>`);
 let quoted;const preview=()=>{try{quoted=openingQuote5(id,el('openDesign5').value,el('openBrand').value,el('openBlend').value);el('openingPreview5').innerHTML=rows([['Adresa a základní vybavení',money(quoted.base)],['Úprava vybavení podle návrhu',money(quoted.changes.cost)],['Celkem při otevření',money(quoted.cost)],['Zůstane v hotovosti',money(quoted.after)],['Místa / průchodnost',quoted.changes.info.seats+' míst · '+number(quoted.changes.info.flow*100,1)+' %'],['Fixní provoz nové pobočky / týden',money(quoted.weekly)]])+`<div class="studio-open-plan5">${floorSvg5(quoted.design.floor)}</div>`+(quoted.after<(weeklyFixed()+quoted.weekly)*4?'<div class="warning">Po otevření zůstane méně než čtyřtýdenní rezerva fixních nákladů celé firmy.</div>':'');el('openConfirm').disabled=state.over||quoted.after<0;}catch(e){quoted=null;el('openingPreview5').textContent=e.message;el('openConfirm').disabled=true;}};
 for(const key of ['openDesign5','openBrand','openBlend'])el(key).onchange=preview;preview();el('openConfirm').onclick=()=>{try{openStore(id,el('openBrand').value,el('openBlend').value,false,el('openDesign5').value,quoted);studioDraft5=null;persist();render();el('modal').close();toast('Kavárna otevřena podle vybraného návrhu.')}catch(e){toast(e.message)}};
};
interiorView=function(){const s=studioCurrent5(),draft=studioDraft5.design;let info,quote,error='';try{info=designInfo5(draft);quote=s&&!s.franchise?designQuote5(s.id,draft):null}catch(e){error=e.message}const selectedItem=draft.floor.items.find(i=>i.id===designSelected),saved=state.studio5.designs.find(d=>d.id===studioTarget5);return `<div class="view-toolbar"><p class="intro">Navrhni prostor, vyber vybavení a ulož celou kavárnu pro další expanzi. Úpravy v pracovním návrhu se zaplatí až při otevření nebo potvrzení přestavby.</p>${field('Upravovaný návrh / kavárna',`<select id="designStore5">${option('new','Nový vlastní návrh',studioTarget5)}${state.studio5.designs.map(d=>option(d.id,'Návrh · '+d.name,studioTarget5)).join('')}${state.stores.map(x=>option(x.id,loc(x.id).name+' · existující kavárna',studioTarget5)).join('')}</select>`)}</div><div class="live-layout"><section class="card"><div class="card-head"><h2>${s?esc(loc(s.id).name):'Tvoje vlastní kavárna'}</h2><span class="badge">Pracovní návrh · 8 × 6</span></div>${floorSvg5(draft.floor,{edit:true,active:designSelected})}<div class="fields">${field('Vybraný prvek',`<select id="designSelected5">${draft.floor.items.map(i=>option(i.id,STATIONS5[i.kind].name+' · '+i.id,designSelected)).join('')}</select>`)}${field('Přidat nábytek',`<select id="furnitureKind5">${Object.entries(FURNITURE5).map(([k,c])=>option(k,STATIONS5[k].name+' · '+money(c.cost),'table2')).join('')}</select>`)}</div><div class="actions"><button class="soft" id="addTable5">Přidat vybraný nábytek</button><button class="soft" id="removeTable5" ${!FURNITURE5[selectedItem?.kind]&&selectedItem?.kind!=='window'?'disabled':''}>Odebrat vybraný prvek</button>${draft.equipment.window&&!draft.floor.items.some(i=>i.kind==='window')?'<button class="soft" id="addWindow5">Umístit okénko</button>':''}<button class="quiet" id="resetFloorDraft5">Vrátit pracovní změny</button></div>${error?`<div class="warning">${esc(error)}</div>`:rows([['Skutečná místa v návrhu',info.seats],['Průchodnost / výkon pohybu',number(info.flow*100,1)+' %'],['Pohyb při přípravě',info.work+' polí'],['Údržba vybavení / týden',money(info.effects.cost)]])}<p class="sub">Malý stolek zabírá jedno pole a má dvě místa. Velký stůl zabírá dvě pole a má čtyři místa. Barové místo zabírá jedno pole. Vchod, východ a přístup ke všem prvkům musí zůstat volné.</p>${quote?.changed?`<div class="studio-quote5"><h3>Rozpočet přestavby</h3>${rows([['Nové vybavení a nábytek',money(quote.purchases)],['Výkup odstraněného vybavení',money(quote.credit)],['Přestavba prostoru',money(quote.renovation)],['Celkem',money(quote.cost)]])}</div>`:''}${s?`<button class="primary wide" id="applyFloor5" ${error||s.franchise||!quote?.changed||state.cash<quote.cost?'disabled':''}>Potvrdit přestavbu</button>`:''}</section><div class="stack"><section class="card"><span class="eyelabel">VYBAVENÍ PRO TENTO NÁVRH</span><h2>Technologie & způsob obsluhy</h2><div class="fields">${field('Způsob obsluhy',`<select id="studioLayout5">${Object.entries(LAYOUT).map(([k,v])=>option(k,v,draft.layout)).join('')}</select>`)}${studioEquipmentFields5(draft)}</div><p class="sub">Compact kávovar a Entry mlýnek jsou součástí základního otevření. Dražší modely mění výkon, kvalitu a údržbu. Filtr, kuchyně a cold brew odemykají položky menu.</p></section><section class="card"><h2>Uložit pro novou pobočku</h2>${field('Název vlastního návrhu',`<input id="studioName5" maxlength="40" value="${esc(studioDraft5.name)}">`)}<div class="actions"><button class="primary" id="saveDesign5" ${error?'disabled':''}>${saved?'Uložit změny návrhu':'Uložit vlastní návrh'}</button>${saved?'<button class="soft" id="copyDesign5">Uložit kopii</button><button class="quiet" id="deleteDesign5">Smazat návrh</button>':''}</div><p class="sub">Uložení návrhu je zdarma. Při otevření nové kavárny ho vybereš v jedné nabídce; použije se celý půdorys, vybavení i způsob obsluhy. Návrhy jsou součástí uložené hry.</p></section>${s?`<section class="card"><h2>Směny této kavárny</h2><div class="fields">${s.daily.shifts.map((n,i)=>field(PERIODS5[i],input('shiftCount5-'+i,n,0,7))).join('')}</div>${rows([['Smluvní mzdy baristů',money(shiftWages5(s))],['Vedení směn',esc(owner5(s)?.person.name||'Zakladatel')]])}<div class="actions"><button class="primary" id="saveShifts5" ${s.franchise?'disabled':''}>Uložit ruční rozpis</button><button class="soft" id="suggestShifts5" ${s.franchise?'disabled':''}>Navrhnout podle špičky</button><button class="soft" data-crew-open="${s.id}">Jmenný tým</button></div><label class="checkbox-line"><input id="shiftAuto5" type="checkbox" ${s.daily.auto?'checked':''}> Povolit automatické směny</label>${field('Odpovědnost',`<select id="shiftOwner5">${option('manager','Vedoucí kavárny',s.daily.owner)}${option('region','Oblastní ředitel',s.daily.owner)}${option('operations','Provozní ředitel',s.daily.owner)}</select>`)}<p class="sub">Mzdy určuje součet smluv skutečných lidí. Ruční rozpis chrání vypnutá automatika.</p></section>`:''}</div></div>`};
menuView=function(){if(!state.stores.length)return studioEmpty5();const s=state.stores.find(s=>s.id===menuStore)||state.stores[0];menuStore=s.id;const previous=STUDIO_UI5.menuView(),index=previous.indexOf('<div class="section-header">');return previous.slice(0,index)+`<div class="section-header"><div><span class="eyelabel">KONKRÉTNÍ MODELY · SKUTEČNÉ NÁKLADY</span><h2>Vybavení kavárny</h2></div><button class="soft" data-studio-store="${s.id}">Půdorys, nábytek & uložený návrh</button></div><div class="cards">${Object.entries(EQUIPMENT_MODELS5).map(([key,models])=>{const item=s.equipment[key],cfg=item&&equipmentSpec5(key,item);return `<section class="card equipment-card"><span class="eyelabel">${esc(EQUIPMENT[key].name)}</span><h3>${cfg?esc(cfg.name):'Zatím bez zařízení'}</h3>${cfg?rows([['Technický stav',round(item.condition)+' %'],['Údržba / týden',money(cfg.maintenance)],['Kapacita při 100 % stavu','+'+round((cfg.capacity-1)*100)+' %'],['Kvalita při 100 % stavu','+'+cfg.quality]]):'<p class="sub">Vyber zařízení podle menu a potřebné kapacity.</p>'}${field('Vybrat model',`<select data-catalog-model="${key}">${Object.entries(models).map(([model,c])=>option(model,c.name+' · '+money(c.cost),item?.model||'standard')).join('')}</select>`)}<div class="actions"><button class="primary" data-equipment="${key}" data-equipped="false" ${s.franchise?'disabled':''}>${item?'Změnit model':'Pořídit vybavení'}</button>${item?`<button class="soft" data-studio-service="${key}" ${s.franchise?'disabled':''}>Servis · ${money(round(cfg.cost*.08))}</button>`:''}</div><p class="sub">Při výměně získáš 35 % původní ceny podle technického stavu. Základní modely mají údržbu zahrnutou v běžném provozu.</p></section>`}).join('')}</div>`};
supplyView=function(){return state.stores.length?STUDIO_UI5.supplyView():studioEmpty5()};
liveView=function(){return state.stores.length?STUDIO_UI5.liveView():studioEmpty5()};
function studioAddItem5(kind){studioCurrent5();const design=studioDraft5.design;let added=false;for(let y=0;y<6&&!added;y++)for(let x=0;x<8&&!added;x++){const candidate={...design.floor,items:[...design.floor.items,{id:kind+'-draft-'+Date.now().toString(36),kind,x,y}]};try{designInfo5({...design,floor:candidate});design.floor=candidate;designSelected=candidate.items.at(-1).id;added=true}catch{}}if(!added)toast('Není volné průchozí místo pro tento prvek.');render()}
bind=function(){STUDIO_UI5.bind();on('[data-studio-new]',()=>{studioTarget5='new';studioDraft5=null;goto('interior')});on('[data-studio-store]',b=>{studioTarget5=b.dataset.studioStore;studioDraft5=null;goto('interior')});if(el('designStore5'))el('designStore5').onchange=()=>{studioTarget5=el('designStore5').value;studioDraft5=null;render()};if(el('studioName5'))el('studioName5').oninput=()=>studioDraft5.name=el('studioName5').value;if(el('studioLayout5'))el('studioLayout5').onchange=()=>{studioDraft5.design.layout=el('studioLayout5').value;render()};on('[data-studio-model]',node=>{const key=node.dataset.studioModel;if(node.value==='none'){delete studioDraft5.design.equipment[key];if(key==='window')studioDraft5.design.floor.items=studioDraft5.design.floor.items.filter(i=>i.kind!=='window')}else studioDraft5.design.equipment[key]=node.value;render()},'change');
 if(el('addTable5'))el('addTable5').onclick=()=>studioAddItem5(el('furnitureKind5').value);if(el('addWindow5'))el('addWindow5').onclick=()=>studioAddItem5('window');if(el('removeTable5'))el('removeTable5').onclick=()=>{studioDraft5.design.floor.items=studioDraft5.design.floor.items.filter(i=>i.id!==designSelected);designSelected='counter';render()};if(el('resetFloorDraft5'))el('resetFloorDraft5').onclick=()=>{studioDraft5=null;render()};if(el('applyFloor5'))el('applyFloor5').onclick=()=>{try{const desired=cloneStudio5(studioDraft5.design),q=designQuote5(designStore,desired);confirmAction('Potvrdit přestavbu?',`Investice ${money(q.cost)} zahrnuje vybavení, nábytek a přestavbu. Výkup ${money(q.credit)} je už odečten.`,()=>{applyDesign5(q.store,desired,q);studioDraft5=null},'Přestavět')}catch(e){toast(e.message)}};
 const save=copy=>{try{const id=!copy&&state.studio5.designs.find(d=>d.id===studioTarget5)?.id,d=saveDesign5(studioDraft5.name,studioDraft5.design,id||null);studioTarget5=d.id;studioDraft5=null;persist();render();toast('Návrh uložen. Vyber ho při otevírání nové kavárny.')}catch(e){toast(e.message)}};if(el('saveDesign5'))el('saveDesign5').onclick=()=>save(false);if(el('copyDesign5'))el('copyDesign5').onclick=()=>save(true);if(el('deleteDesign5'))el('deleteDesign5').onclick=()=>confirmAction('Smazat uložený návrh?','Otevřené kavárny už mají vlastní vybavení a půdorys.',()=>{deleteDesign5(studioTarget5);studioTarget5='new';studioDraft5=null},'Smazat návrh');
 on('[data-equipment]',b=>{try{const key=b.dataset.equipment,model=document.querySelector(`[data-catalog-model="${key}"]`).value,q=equipmentQuote5(menuStore,key,model);if(q.same){toast('Tento model už je instalovaný. Pro obnovení stavu použij servis.');return}confirmAction('Pořídit '+EQUIPMENT_MODELS5[key][model].name+'?',`Cena ${money(q.price)}, výkup ${money(q.credit)}. Zaplatíš ${money(q.cost)}; údržba ${money(q.weekly)} týdně.`,()=>buyEquipmentModel5(menuStore,key,model,q),'Pořídit model')}catch(e){toast(e.message)}});on('[data-studio-service]',b=>act(()=>serviceEquipment(menuStore,b.dataset.studioService),'Zařízení po servisu.'));
};
render=function(){if(studioState5!==state){studioState5=state;studioTarget5=state.stores[0]?.id||'new';studioDraft5=null;selected=null;floorDraft=null;}STUDIO_UI5.render()};
help=function(){STUDIO_UI5.help();const ps=el('modalContent').querySelectorAll('p');for(const p of ps)if(p.textContent.startsWith('Začátek:'))p.innerHTML='<strong>Začátek:</strong> Ve scénáři Zakladatel začínáš s 650 000 Kč, pražírnou a zásobami. První kavárnu si vyber na mapě. Studio kaváren umožní uložit vlastní návrh ještě před otevřením. Ponech si rezervu na mzdy, nájem a výrobu.';const p=document.createElement('p');p.textContent='Studio kaváren: malé dvoumístné stolky, čtyřmístné stoly a jednotlivá barová místa mají skutečnou cenu, velikost a kapacitu. Kávovary a mlýnky mají více modelů. Ulož celý návrh a při nové expanzi ho vyber v nabídce. Uložení nic nestojí; otevírání a přestavba zobrazí rozpočet před potvrzením. Při výměně vybavení je výkup 35 % ceny podle stavu. Starší rozehrané firmy si ponechají hotovost i pobočky.';el('modalContent').append(p)};el('help').onclick=help;
render();
